#!/usr/bin/env bash
# test-seatbelt-audit-path.sh -- the benchmarker's private audit file
# (BENCHD_PRIVATE_AUDIT_PATH: retained, unredacted engine diagnostics) is denied
# to entry code in all three profiles: the CLI (transform), the build and the
# resident. Each profile is generated by tools/seatbelt-profile.py and must end
# with a deny of the resolved path, after every allow.
set -uo pipefail
cd "$(dirname "$0")/.."
WORK="$(mktemp -d)"; trap 'rm -rf "${WORK}"' EXIT
AUDIT="${WORK}/private/audit.json"; mkdir -p "${WORK}/private"; printf '{}' > "${AUDIT}"
REAL="$(cd "${WORK}/private" && pwd -P)/audit.json"
RULE="(deny file-read* file-write* (subpath \"${REAL}\"))"
FAILS=0
for kind in cli build resident; do
  case "${kind}" in
    cli) args=(--exec /usr/bin/true --write-subpath "${WORK}/out") ;;
    build) args=(--build --write-subpath "${WORK}/build") ;;
    resident) args=(--exec /usr/bin/true --deny-subpath "${WORK}/logs" --write-subpath "${WORK}/logs/tmp.1" --unix-socket "${WORK}/s.sock") ;;
  esac
  prof="$(BENCHD_PRIVATE_AUDIT_PATH="${AUDIT}" python3 tools/seatbelt-profile.py "${args[@]}")"
  last_allow="$(grep -n '^(allow' <<< "${prof}" | tail -1 | cut -d: -f1)"
  deny_at="$(grep -nF "${RULE}" <<< "${prof}" | head -1 | cut -d: -f1)"
  if [[ -n "${deny_at}" && "${deny_at}" -gt "${last_allow:-0}" ]]; then
    echo "ok    the ${kind} profile denies the private audit path after every allow"
  else
    echo "FAIL  the ${kind} profile does not deny ${REAL}"; FAILS=$((FAILS + 1))
  fi
done
if [[ -x /usr/bin/sandbox-exec ]]; then
  BENCHD_PRIVATE_AUDIT_PATH="${AUDIT}" python3 tools/seatbelt-profile.py --exec /bin/cat > "${WORK}/p.sb"
  if /usr/bin/sandbox-exec -f "${WORK}/p.sb" /bin/cat "${AUDIT}" >/dev/null 2>&1; then
    echo "FAIL  a process under sandbox-exec read the private audit file"; FAILS=$((FAILS + 1))
  else
    echo "ok    a process under sandbox-exec cannot read the private audit file"
  fi
else
  echo "SKIP (needs macOS)  the sandbox-exec read check: no /usr/bin/sandbox-exec on this host"
fi
if [[ ${FAILS} -eq 0 ]]; then echo "test-seatbelt-audit-path.sh: all cases passed"; exit 0; fi
echo "test-seatbelt-audit-path.sh: ${FAILS} case(s) failed"; exit 1
